package fixture

import "testing"

func TestClamp(t *testing.T) {
	cases := [][3]int{{5, 1, 3}, {-1, 0, 10}, {5, 1, 10}}
	want := []int{3, 0, 5}
	for i, c := range cases {
		if got := Clamp(c[0], c[1], c[2]); got != want[i] {
			t.Fatalf("Clamp(%v) = %d, want %d", c, got, want[i])
		}
	}
}
